from tastypie.resources import ModelResource
from tastypie.authentication import ApiKeyAuthentication
from tastypie.utils import trailing_slash
from django.urls import re_path
from django.http import JsonResponse, Http404, HttpResponseForbidden
from .models import IndustrialDeviceLog

class DeviceTelemetryResource(ModelResource):
    class Meta:
        queryset = IndustrialDeviceLog.objects.all()
        resource_name = 'telemetry'
        authentication = ApiKeyAuthentication()

    def prepend_urls(self):
        return [
            re_path(r"^(?P<resource_name>%s)/(?P<pk>\w[\w/-]*)/export%s$" % (
                self._meta.resource_name, trailing_slash()),
                self.wrap_view('export_log'), name="api_telemetry_export"),
        ]

    def export_log(self, request, **kwargs):
        self.is_authenticated(request)
        try:
            log = IndustrialDeviceLog.objects.get(pk=kwargs['pk'])
        except IndustrialDeviceLog.DoesNotExist:
            raise Http404('Log not found')

        # Ensure the log belongs to a device installed in the user's authorized facility
        if log.device.facility != request.user.facility:
            return HttpResponseForbidden('Access denied to telemetry from this facility')

        return JsonResponse({
            'device_id': log.device_id,
            'firmware_version': log.firmware_version,
            'telemetry_dump': log.payload_data
        })
